import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.YT-FC_Xx.js";const g=JSON.parse('{"title":"导入节点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/import.md","filePath":"guide/import.md","lastUpdated":1793060292000}'),i={name:"guide/import.md"};function l(s,e,n,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="导入节点" tabindex="-1">导入节点 <a class="header-anchor" href="#导入节点" aria-label="Permalink to &quot;导入节点&quot;">​</a></h1><p>在 <strong>节点</strong> 页点 <strong>更多 → 导入节点</strong>，可以把不是面板部署的节点（脚本搭的、没装 agent 的机器、机场节点）加进来，用来对接中转和加入订阅。转换规则参考 Sub-Store：所有格式先转成 Mihomo（Clash Meta）节点格式保存，再按订阅格式输出，参数不会丢失。</p><h2 id="支持的输入" tabindex="-1">支持的输入 <a class="header-anchor" href="#支持的输入" aria-label="Permalink to &quot;支持的输入&quot;">​</a></h2><ul><li>分享链接（每行一个）：<code>ss://</code>（含 obfs / v2ray-plugin / shadow-tls 插件）、<code>vmess://</code>（v2rayN 格式）、<code>vless://</code>（含 Reality、WS、gRPC、H2、XHTTP）、<code>trojan://</code>、<code>hysteria2://</code> / <code>hy2://</code>、<code>tuic://</code>、<code>anytls://</code>、<code>socks5://</code></li><li>base64 订阅内容</li><li>Clash / Mihomo 配置（读取 <code>proxies</code>）</li><li>sing-box 配置（读取 <code>outbounds</code>）</li><li>Surge / Loon 节点行，例如 <code>名称 = snell, 1.2.3.4, 6160, psk=..., version=4</code></li><li>订阅文件：点 <strong>选择订阅文件</strong>，内容可以是上面任意一种，最大 5MB。打开 <strong>存为订阅源</strong> 会存成文件订阅源，以后重新上传就能更新</li><li>订阅地址（<code>https://...</code>）：面板服务器会以 Mihomo 的身份去下载，拿到的通常是参数最完整的 Clash 配置。打开 <strong>定时同步</strong>（默认打开）会存成 <a href="./subscription-sources#订阅源">订阅源</a>，按时更新；关掉则只导入一次</li></ul><h2 id="手动填写" tabindex="-1">手动填写 <a class="header-anchor" href="#手动填写" aria-label="Permalink to &quot;手动填写&quot;">​</a></h2><p>没有现成的链接时，在导入窗口顶部切到 <strong>手动填写</strong>，选协议后逐项填写地址、端口、密码 / UUID，以及 TLS / Reality、传输方式（TCP / WebSocket / gRPC）等参数。支持 Shadowsocks、VLESS、VMess、Trojan、Hysteria2、TUIC v5、AnyTLS、SOCKS5。名称留空时用“地址:端口”。填好的内容会按分享链接的格式保存，和粘贴链接导入的节点完全一样。</p><h2 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h2><p>节点多了可以打标签区分，比如“出站”“落地”“香港”：</p><ul><li>导入或手动填写时可以直接填标签（存为订阅源时不填）</li><li>已有的节点：点击节点 → <strong>标签</strong>；面板自建的入站也可以打标签</li><li>批量：<strong>更多 → 批量操作</strong>，选中节点后点 <strong>标签</strong>，会替换选中节点原来的标签</li><li>列表上方的 <strong>全部标签</strong> 下拉框按标签筛选，搜索框也能搜标签</li></ul><p>标签只用于在面板里区分和筛选，不影响订阅和分享。每个节点最多 10 个标签，每个不超过 20 字，不能包含逗号。</p><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>暂不支持 WireGuard、SSR、Hysteria v1 等类型，导入时会逐条提示</li><li>经中转连接时，原节点用域名连接的，会自动把域名保留为 TLS SNI 和 WebSocket Host；Hysteria2 端口跳跃只在直连线路上保留</li><li>面板不会部署、修改这些节点，也没有流量统计、白名单、换密钥等功能</li><li>原节点的地址或参数变了，点击该节点 → <strong>编辑</strong>，修改地址或粘贴新的链接替换参数，相关中转会自动指向新地址</li><li>勾选“只通过我的转发访问”后，订阅和分享中不再包含直连线路，只放你自己机器上的中转线路（该节点没有中转时就不会出现在订阅里）</li><li>删除只会删除面板里的记录和相关中转，不影响原服务器</li><li>同一个地址和端口不会重复导入</li></ul><h2 id="连通性" tabindex="-1">连通性 <a class="header-anchor" href="#连通性" aria-label="Permalink to &quot;连通性&quot;">​</a></h2><p>面板每 3 分钟检测一次导入的节点能不能连上，结果显示在卡片上；导入的节点没有 agent，所以只有这种从面板发起的检测，没有到各地测试点的延迟。详见 <a href="./latency#连通性检测">延迟与回程 - 连通性检测</a>。</p><h2 id="对接中转" tabindex="-1">对接中转 <a class="header-anchor" href="#对接中转" aria-label="Permalink to &quot;对接中转&quot;">​</a></h2><p>导入后的节点和面板部署的入站一样：点击节点 → <strong>中转</strong> → 选择隧道即可，端口转发和隧道转发（包括经 IX 的多跳）都可以用。见 <a href="./relay">对接中转</a>。</p>',16)])])}const p=o(i,[["render",l]]);export{g as __pageData,p as default};
